import{_ as t,o,c as a,al as i}from"./chunks/framework.7vp1BMOE.js";const p=JSON.parse('{"title":"Test MC_07 - Optical Flow Low Sensor","description":"","frontmatter":{},"headers":[],"relativePath":"ko/test_cards/mc_07_optical_flow_low_mount.md","filePath":"ko/test_cards/mc_07_optical_flow_low_mount.md"}'),r={name:"ko/test_cards/mc_07_optical_flow_low_mount.md"};function l(n,e,s,c,h,_){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="test-mc-07-optical-flow-low-sensor" tabindex="-1">Test MC_07 - Optical Flow Low Sensor <a class="header-anchor" href="#test-mc-07-optical-flow-low-sensor" aria-label="Permalink to &quot;Test MC_07 - Optical Flow Low Sensor&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Test that optical flow works as expected with a low mounted optical flow sensor</p><h2 id="preflight" tabindex="-1">Preflight <a class="header-anchor" href="#preflight" aria-label="Permalink to &quot;Preflight&quot;">​</a></h2><p>Ensure that the drone&#39;s optical flow sensor is mounted more than an inch off of the ground</p><p>Ensure that <a href="./../advanced_config/parameter_reference#MPC_THR_MIN">MPC_THR_MIN</a> is tuned correctly for landing</p><p>Disconnect all GPS / compasses and ensure vehicle is using optical flow for navigation (<a href="./../sensor/optical_flow">Setup Information here</a>)</p><p>Ensure there are no other sources of positioning besides optical flow</p><ul><li><a href="./../advanced_config/parameter_reference#EKF2_OF_CTRL">EKF2_OF_CTRL</a>: <code>1</code></li><li><a href="./../advanced_config/parameter_reference#EKF2_GPS_CTRL">EKF2_GPS_CTRL</a>: <code>0</code></li><li><a href="./../advanced_config/parameter_reference#EKF2_EV_CTRL">EKF2_EV_CTRL</a>: <code>0</code></li></ul><p>Ensure that the drone can go into <a href="./../flight_modes_mc/position">Position mode</a> while still on the ground</p><h2 id="flight-tests" tabindex="-1">Flight Tests <a class="header-anchor" href="#flight-tests" aria-label="Permalink to &quot;Flight Tests&quot;">​</a></h2><p>❏ <a href="./../flight_modes_mc/position">Position mode</a></p><p>    ❏ Horizontal position should hold current value with stick centered</p><p>    ❏ Vertical position should hold current value with stick centered</p><p>    ❏ Throttle response set to climb/descent rate</p><p>    ❏ Pitch/Roll/Yaw response set to pitch/roll/yaw rates</p><h2 id="착륙" tabindex="-1">착륙 <a class="header-anchor" href="#착륙" aria-label="Permalink to &quot;착륙&quot;">​</a></h2><p>❏ Land in Position mode with the throttle below 40%</p><p>❏ Upon touching ground, copter should disarm automatically within 2 seconds (default: see <a href="./../advanced_config/parameter_reference#COM_DISARM_LAND">COM_DISARM_LAND</a>)</p><h2 id="예상-결과" tabindex="-1">예상 결과 <a class="header-anchor" href="#예상-결과" aria-label="Permalink to &quot;예상 결과&quot;">​</a></h2><ul><li>추력을 올릴 때 서서히 이륙한다</li><li>Drone should stay in Position mode, NOT fall into <a href="./../flight_modes_mc/altitude">altitude</a> mode</li></ul>',21)])])}const f=t(r,[["render",l]]);export{p as __pageData,f as default};
